def transform(grid):
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            counts = {}
            for i in range(r, min(r + 3, len(grid))):
                for j in range(c, min(c + 3, len(grid[0]))):
                    color = grid[i][j]
                    if color != 5:
                        counts[color] = counts.get(color, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 5)
        out.append(row)
    return out
